  }
  if (options === undefined) options = {};
  if (!options || typeof options !== 'object' || Array.isArray(options)) {
    throw new TypeError('options must be an object');
  }
  if (token !== null && token !== undefined &&
      (typeof token !== 'string' || token.length === 0)) {
    throw new TypeError('token must be non-empty when provided');
  }

  const methodValue = options.method === undefined ? 'GET' : options.method;
  if (typeof methodValue !== 'string') throw new TypeError('method must be a string');
  const method = methodValue.toUpperCase();
  if (method !== 'GET' && method !== 'POST') throw new RangeError('Unsupported method');

  const suppliedHeaders = options.headers === undefined ? {} : options.headers;
  if (!suppliedHeaders || typeof suppliedHeaders !== 'object' || Array.isArray(suppliedHeaders)) {
    throw new TypeError('headers must be an object');
  }
  const headers = {};
  for (const key of Object.keys(suppliedHeaders)) {
    if (typeof suppliedHeaders[key] !== 'string') {
      throw new TypeError('header values must be strings');
    }
    headers[key] = suppliedHeaders[key];
  }
  headers['Content-Type'] = 'application/json';
  if (token !== null && token !== undefined) {
    headers.Authorization = token;
  }

  const hasBody = Object.prototype.hasOwnProperty.call(options, 'body');
  let body = null;
  if (method === 'GET' && hasBody) throw new TypeError('GET cannot have a body');
  if (method === 'POST') {
    if (!hasBody) throw new TypeError('POST requires a body');
    try {
      body = JSON.stringify(options.body);
    } catch (error) {
      throw new TypeError('Body is not JSON serializable');
    }
    if (body === undefined) throw new TypeError('Body is not JSON serializable');
  }

  const normalizedBase = baseUrl.replace(/\/+$/, '');
  return { url: normalizedBase + endpoint, method, headers, body };
