'use strict';
const assert = require('node:assert/strict');
const buildRequestDescriptor = require('./solution');
assert.equal(typeof buildRequestDescriptor, 'function');

const getOptions = Object.freeze({
  method: 'gEt',
  headers: Object.freeze({ Accept: 'text/plain', 'Content-Type': 'wrong' })
});
const getResult = buildRequestDescriptor('https://example.test///', '/items?q=1', getOptions, 'secret');
assert.deepEqual(getResult, {
  url: 'https://example.test/items?q=1',
  method: 'GET',
  headers: {
    Accept: 'text/plain',
    'Content-Type': 'application/json',
    Authorization: 'Bearer secret'
  },
  body: null
});
assert.notStrictEqual(getResult.headers, getOptions.headers);
assert.deepEqual(getOptions, { method: 'gEt', headers: { Accept: 'text/plain', 'Content-Type': 'wrong' } });

assert.deepEqual(buildRequestDescriptor('http://x', '/a'), {
  url: 'http://x/a', method: 'GET', headers: { 'Content-Type': 'application/json' }, body: null
});
const body = Object.freeze({ z: 1, nested: Object.freeze(['x']) });
const postOptions = Object.freeze({ method: 'post', headers: Object.freeze({ X: 'y' }), body });
assert.deepEqual(buildRequestDescriptor('http://x/', '/submit', postOptions, null), {
  url: 'http://x/submit',
  method: 'POST',
  headers: { X: 'y', 'Content-Type': 'application/json' },
  body: '{"z":1,"nested":["x"]}'
});
assert.deepEqual(postOptions.body, { z: 1, nested: ['x'] });

assert.throws(() => buildRequestDescriptor('', '/x'), TypeError);
assert.throws(() => buildRequestDescriptor(1, '/x'), TypeError);
assert.throws(() => buildRequestDescriptor('http://x', 'x'), TypeError);
assert.throws(() => buildRequestDescriptor('http://x', '/x', []), TypeError);
assert.throws(() => buildRequestDescriptor('http://x', '/x', null), TypeError);
assert.throws(() => buildRequestDescriptor('http://x', '/x', { method: 'PUT' }), RangeError);
assert.throws(() => buildRequestDescriptor('http://x', '/x', { headers: [] }), TypeError);
assert.throws(() => buildRequestDescriptor('http://x', '/x', { headers: { X: 1 } }), TypeError);
assert.throws(() => buildRequestDescriptor('http://x', '/x', { body: undefined }), TypeError);
assert.throws(() => buildRequestDescriptor('http://x', '/x', { method: 'POST' }), TypeError);
assert.throws(() => buildRequestDescriptor('http://x', '/x', { method: 'POST', body: undefined }), TypeError);
assert.throws(() => buildRequestDescriptor('http://x', '/x', { method: 'POST', body: 1n }), TypeError);
assert.throws(() => buildRequestDescriptor('http://x', '/x', {}, ''), TypeError);
assert.throws(() => buildRequestDescriptor('http://x', '/x', {}, 123), TypeError);

